 print('==',dom)
 try: d=plistlib.loads(p)
 except Exception as e: print(e); continue
 for k,v in d.items():
  if isinstance(v, bytes):
   print(k, 'bytes',len(v))
   for fmt in ['bplist','json']:
    try:
     x=plistlib.loads(v) if fmt=='bplist' else __import__('json').loads(v)
     print(' ',fmt, pprint.pformat(x)[:1500])
     break
    except Exception: pass
  else: print(k,v)
PY"

